int remove_duplicates(int *a, int n) {
    if (n == 0) return 0;
    int k = 1;                       /* k 指向下一个可写入位置 */
    for (int i = 1; i < n; i++)
        if (a[i] != a[k - 1]) a[k++] = a[i];
    return k;
}

/* 迭代：O(N) 时间，O(1) 空间 */
Node *reverse_list(Node *head) {
    Node *prev = NULL, *cur = head;
    while (cur) {
        Node *next = cur->next;   /* 1. 先保存后继 */
        cur->next = prev;         /* 2. 掉转方向 */
        prev = cur;               /* 3. 前移 */
        cur = next;               /* 4. 前移 */
    }
    return prev;                  /* prev 最终指向原尾节点＝新头 */
}

Node *detect_cycle(Node *head) {
    Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {                 /* 相遇 */
            Node *p = head;
            while (p != slow) { p = p->next; slow = slow->next; }
            return p;                       /* 入口 */
        }
    }
    return NULL;
}
